var NAMES=["sonar_sweep","sonar_sweep_id","servo_angle","relay_on","buzzer_hz","buzzer_ms","btn1","btn2","btn3","btn4","ptp_offset_ns","ptp_state","ptp_locked","last_seen","tsn_app_vlan","tsn_app_prio","tsn_app_preempt","tsn_app_timesync","tsn_app_strole","tsn_app_stvlan","tsn_app_tascyc","tsn_features"];
var dv=(msg.payload||[]);
var tele={};
for(var i=0;i<NAMES.length;i++){var d=dv[i];tele[NAMES[i]]=(d&&d.value)?d.value.value:null;}
global.set("HTSN_TELE",tele);
var b=[tele.btn1,tele.btn2,tele.btn3,tele.btn4].join(",");
return [
 {payload:(typeof tele.servo_angle==="number")?tele.servo_angle:0},
 {payload:"state="+tele.ptp_state+" locked="+tele.ptp_locked+" off="+(tele.ptp_offset_ns||0)+"ns lastseen="+(tele.last_seen||0)},
 {payload:"vlan="+tele.tsn_app_vlan+" prio="+tele.tsn_app_prio+" ts="+tele.tsn_app_timesync+" role="+tele.tsn_app_strole+" feat="+tele.tsn_features+" tasns="+(tele.tsn_app_tascyc||0)},
 {payload:"relay="+tele.relay_on+" buzz="+(tele.buzzer_hz||0)+"Hz sonar#="+tele.sonar_sweep_id+" btns=["+b+"]"},
 {payload:"servo="+tele.servo_angle+" ptp="+tele.ptp_state+" feat="+tele.tsn_features+" vlan="+tele.tsn_app_vlan+" @ "+new Date().toLocaleTimeString()}
];

var p=msg.payload;
if(p===null||p===undefined){p="";}
msg.payload="["+msg.topic+"] "+p;
return msg;

var f=msg.payload||{};
function N(v,d){var n=parseInt(v,10);return isNaN(n)?d:n;}
var gs=[],dur=[];
(String(f.gcl||"")).trim().split(/\s+/).forEach(function(p){var a=p.split(":");if(a.length===2){var s=parseInt(a[0],10),d=parseInt(a[1],10);if(!isNaN(s)&&!isNaN(d)){gs.push(s);dur.push(d);}}});
var TM={"none":0,"GM":1,"slave":2},SR={"talker":1,"listener":2};
var tm=(TM[f.timesync_mode]!==undefined)?TM[f.timesync_mode]:N(f.timesync_mode,0);
var sr=(SR[f.st_role]!==undefined)?SR[f.st_role]:N(f.st_role,0);
var flat={priority:N(f.priority,0),traffic_class:N(f.traffic_class,0),vlan_id:N(f.vlan_id,0),preemption:N(f.preemption,0),timesync_mode:tm,st_role:sr,st_vlan:N(f.st_vlan,0),st_prio:N(f.st_prio,0),tas_cycle_ns:N(f.tas_cycle_ns,0),gcl_gs:gs,gcl_dur:dur};
msg.datatype="String";msg.topic="ns=1;i=51";
msg.payload=JSON.stringify(flat);
global.set("HTSN_LAST_CFG",flat);
node.status({fill:"green",shape:"dot",text:"apply "+msg.payload.length+"B"});
return msg;

var t=global.get("HTSN_TELE")||{};
function g(v){return (v===null||v===undefined)?"-":v;}
msg.payload="vlan="+g(t.tsn_app_vlan)+" prio="+g(t.tsn_app_prio)+" pre="+g(t.tsn_app_preempt)+" ts="+g(t.tsn_app_timesync)+" role="+g(t.tsn_app_strole)+" sval="+g(t.tsn_app_stvlan)+" tasns="+g(t.tsn_app_tascyc)+" feat=0x"+(g(t.tsn_features|0)).toString(16);
return msg;
